-- Additive extended publisher fields, atomic with account changes.
create or replace function public.ca_v2_save_person(p_cong_id text,p_person jsonb,p_shared boolean default false) returns jsonb language plpgsql security definer set search_path='' as $$declare person_id text=p_person->>'id';new_email text=lower(btrim(coalesce(p_person->>'email','')));g public.service_groups;expected jsonb;begin perform ca_private.v2_require(p_cong_id,array['admin']);perform pg_advisory_xact_lock(hashtextextended('publisher-login:'||p_cong_id,0));if coalesce(p_person->>'gender','Male') not in('Male','Female') then raise exception 'Choose a supported gender';end if;if length(coalesce(person_id,'')) not between 1 and 100 or length(btrim(coalesce(p_person->>'name',''))) not between 1 and 300 then raise exception 'Publisher name and ID required';end if;if new_email<>'' and(new_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' or length(new_email)>254) then raise exception 'Invalid email';end if;if exists(select 1 from public.publishers where id=person_id and (cong_id<>p_cong_id or transferred_at is not null)) then raise exception 'Publisher cannot be modified in this congregation' using errcode='42501';end if;if new_email<>'' and not p_shared and exists(select 1 from public.congregation_access where cong_id=p_cong_id and role='publisher' and active and congregation_access.email=new_email and publisher_id<>person_id) then raise exception 'Confirm household reporting or choose a different email';end if;if nullif(btrim(p_person->>'group'),'') is not null then select * into g from public.service_groups where cong_id=p_cong_id and name_key=lower(regexp_replace(btrim(p_person->>'group'),'\s+',' ','g')) and archived_at is null;if not found then raise exception 'Choose an existing group';end if;end if;if p_person ? 'familyHeadId' and nullif(p_person->>'familyHeadId','') is not null then
 if p_person->>'familyHeadId'=person_id or not exists(select 1 from public.publishers where id=p_person->>'familyHeadId' and cong_id=p_cong_id and transferred_at is null and family_head_id is null) then raise exception 'Choose an active household head in this congregation' using errcode='22023';end if;
end if;
if nullif(p_person->>'dob','') is not null then perform (p_person->>'dob')::date;end if;
if nullif(p_person->>'baptized','') is not null then perform (p_person->>'baptized')::date;end if;
insert into public.publishers(id,cong_id,name,group_id,service_group,phone,address,gender) values(person_id,p_cong_id,btrim(p_person->>'name'),g.id,g.name,left(coalesce(p_person->>'phone',''),30),left(coalesce(p_person->>'address',''),2000),coalesce(p_person->>'gender','Male')) on conflict(id) do update set name=excluded.name,group_id=excluded.group_id,service_group=excluded.service_group,phone=excluded.phone,address=excluded.address,gender=excluded.gender;expected=public.get_publisher_login(p_cong_id,person_id);if coalesce(p_person->'expected_login','[]'::jsonb) is distinct from expected then raise exception 'Login changed on another device. Reopen the record before saving.' using errcode='40001';end if;perform public.set_publisher_login(p_cong_id,person_id,expected,new_email);update public.publishers set dob=case when p_person ? 'dob' then nullif(left(p_person->>'dob',300),'') else dob end,baptized=case when p_person ? 'baptized' then nullif(left(p_person->>'baptized',300),'') else baptized end,hope=case when p_person ? 'hope' then nullif(left(p_person->>'hope',300),'') else hope end,family_head_id=case when p_person ? 'familyHeadId' then nullif(left(p_person->>'familyHeadId',100),'') else family_head_id end,emergency_name=case when p_person ? 'emergencyName' then nullif(left(p_person->>'emergencyName',300),'') else emergency_name end,emergency_relationship=case when p_person ? 'emergencyRelationship' then nullif(left(p_person->>'emergencyRelationship',300),'') else emergency_relationship end,emergency_phone=case when p_person ? 'emergencyPhone' then nullif(left(p_person->>'emergencyPhone',30),'') else emergency_phone end,spiritual_status=case when p_person ? 'spiritualStatus' then nullif(left(p_person->>'spiritualStatus',300),'') else spiritual_status end,is_elder=case when p_person ? 'isElder' then coalesce((p_person->>'isElder')::boolean,false) else is_elder end,is_ms=case when p_person ? 'isMS' then coalesce((p_person->>'isMS')::boolean,false) else is_ms end,is_rp=case when p_person ? 'isRP' then coalesce((p_person->>'isRP')::boolean,false) else is_rp end,is_sp=case when p_person ? 'isSP' then coalesce((p_person->>'isSP')::boolean,false) else is_sp end,is_fm=case when p_person ? 'isFM' then coalesce((p_person->>'isFM')::boolean,false) else is_fm end where id=person_id and cong_id=p_cong_id;return jsonb_build_object('id',person_id,'saved',true);end $$;

create or replace function public.ca_v2_people(p_cong_id text) returns jsonb language plpgsql stable security definer set search_path='' as $$begin perform ca_private.v2_require(p_cong_id,array['admin']);return(select coalesce(jsonb_agg(to_jsonb(p)||jsonb_build_object('group',coalesce(p.service_group,''),'email',coalesce(public.get_publisher_login(p_cong_id,p.id)->>0,''),'isElder',p.is_elder,'isMS',p.is_ms,'isRP',p.is_rp,'isSP',p.is_sp,'isFM',p.is_fm,'familyHeadId',p.family_head_id,'emergencyName',p.emergency_name,'emergencyRelationship',p.emergency_relationship,'emergencyPhone',p.emergency_phone,'spiritualStatus',p.spiritual_status) order by p.name),'[]') from public.publishers p where p.cong_id=p_cong_id and p.transferred_at is null);end $$;
create or replace function public.ca_v2_capabilities(p_cong_id text) returns jsonb language plpgsql stable security definer set search_path='' as $$begin perform ca_private.v2_require(p_cong_id,array['admin','field_service','attendance','oclm','weekend','group_overseer','publisher','attendant','av','cleaning']);return jsonb_build_object('schema_version',3,'groups',true,'weekend',true,'setup',true,'people',true,'extended_people',true,'private',false,'e2ee_claims',false);end $$;
